export function evaluate({inputs,time}){
const u=inputs.launchSpeed,g=inputs.gravity;
const T=u/g,H=u*u/(2*g);
const t=Math.min(Math.max(time,0),2*T);
const y=u*t-g*t*t/2;
const v=u-g*t;
const rel=t>=T-1e-9;
const yd=rel?y:H;
const vd=rel?(t>T+1e-9?-g*(t-T):0):0;
const ad=rel&&t>T+1e-9?-g:(rel?-g:0);
const ad2=t>=T?-g:0;
const yy=m=>360-m/2.2*270;
const o=[];
o.push(...sdk.panel({id:'lane.toss',x:20,y:40,w:290,h:360,title:'Toss',state:t<1e-9?'At launch':Math.abs(t-T)<1e-9?'At the top':t<T?'Rising':t>=2*T-1e-9?'At launch height':'Falling'}));
o.push(...sdk.panel({id:'lane.drop',x:330,y:40,w:290,h:360,title:'Drop',state:!rel?'Held in place':t<T+0.05?'Just released':t>=2*T-1e-9?'At launch height':'Falling together'}));
const cx1=165,cx2=475;
o.push(...sdk.groundMark('mark.toss',cx1,360,120,'launch'));
o.push(...sdk.gate('gate',cx2,yy(H)+22,{open:rel}));
o.push(sdk.circle('ball.toss',cx1,yy(y),26));
o.push(sdk.circle('ball.drop',cx2,yy(yd),26));
const s=14;
o.push(...sdk.vector('vec.v.toss',{x:cx1-30,y:yy(y)},{value:v,direction:'up'},{scale:s,label:'v'}));
o.push(...sdk.vector('vec.a.toss',{x:cx1+30,y:yy(y)},{value:-g,direction:'up'},{scale:s*0.6,label:'a'}));
o.push(...sdk.vector('vec.v.drop',{x:cx2-30,y:yy(yd)},{value:vd,direction:'up'},{scale:s,label:'v'}));
o.push(...sdk.vector('vec.a.drop',{x:cx2+30,y:yy(yd)},{value:ad2,direction:'up'},{scale:s*0.6,label:'a'}));
o.push(...sdk.callout(cx1+45,yy(y)-50,['v '+sdk.format(v,2)+' m/s','a '+sdk.format(-g,1)+' m/s²'],{id:'callout.toss'}));
o.push(...sdk.callout(cx2+45,yy(yd)-50,['v '+sdk.format(vd,2)+' m/s','a '+sdk.format(ad2,1)+' m/s²'],{id:'callout.drop'}));
return {frame:{width:640,height:420,objects:o,readouts:[{id:'tossedVelocity',value:v},{id:'tossedAcceleration',value:-g},{id:'dropVelocity',value:vd},{id:'dropAcceleration',value:ad2}]},quantities:{launchSpeed:u,gravity:g,apexTime:T,apexHeight:H,tossedVelocity:v,tossedAcceleration:-g,tossedHeight:y,dropVelocity:vd,dropAcceleration:ad2,dropHeight:yd}};}
